            // Reward: high for low slack, drops off exponentially
            score -= 82.0 * (1.0 - (slack / bin_capacity as f64).powf(0.52));
        } else {
            // Penalty for blocking the next item
            score += 75.0;
        }
    }

    // 3. Dynamic New Bin Constraint:
    // Heavily penalize opening new bins. 
    if bin_residual == bin_capacity {
        score += 125.0 + (open_bins_count as f64 * 5.0);
        // If the mean residual is high, we have capacity in existing bins; make new bin very unattractive.
        if mean_residual > 13.0 {
            score += 70.0;
        }
        // Penalize opening a new bin for small items that could likely fit elsewhere.
        if item_size < 40 {
            score += 55.0;
        }
    }

