        let fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 55.0 * fit_tightness;
    }

    // New Bin Logic: Dynamic thresholding based on current packing density.
    if is_new_bin {
        // Penalty grows with open_bins_count to force consolidation.
        score += 85.0 + (open_bins_count as f64 * 2.2);

        // If the mean residual is high, we have enough buffer in existing bins to avoid new ones.
        if mean_residual > 25.0 {
            score += 45.0;
        }
    } else {
        // Scarcity bonus: Force selection if no other options exist.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // Terminal phase: Shift to "First Fit" style to clear remaining items.
    if progress > 0.82 {
        score -= (bin_capacity - post_residual) as f64 * 0.65;
    }

    // Variance control: Penalize deviation from the mean residual to maintain uniform bin states.
    // This reduces the likelihood of creating "orphan" bins with very high residuals.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    // Non-linear penalty for "near-full" bins that are slightly too small for average incoming items.
    // This prevents creating bins that will likely remain at ~10% capacity.
    if post_residual > 0 && post_residual < 15 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
