    score += harmonic_penalty;

    // 3. Lookahead Logic: 
    // If the next item can fit in this post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Thresholding: 
    // If post_residual is small (e.g., < 10), it's "dead space". Penalize it 
    // unless it's 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Contextual Pressure: 
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // avoid opening a new bin at all costs.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. New Bin Penalty:
    // If we are evaluating the empty bin (new bin), apply a structural penalty 
    // proportional to the number of bins already open to encourage consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // Discourage new bin if we haven't reached a reasonable utilization
        if mean_residual > 30.0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
