    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 48.0 * fit_tightness;
    } else if next_item_size > 0 && post_residual < next_item_size && bin_residual != bin_capacity {
        // Penalty for blocking the next item if we have other choices.
        score += 20.0;
    }

    // New Bin Logic: Dynamic thresholding to force tighter compaction.
    if bin_residual == bin_capacity {
        // Higher base penalty to suppress new bin creation unless necessary.
        score += 72.0 + (open_bins_count as f64 * 1.8);

        // If mean_residual is high, we are under-filling existing bins; penalize expansion.
        if mean_residual > 25.0 {
