    }

    // Late-stream optimization: In the final 20%, prioritize clearing residual capacity
    // to consolidate items into fewer active bins.
    if progress > 0.80 {
        score -= (bin_capacity - post_residual) as f64 * 0.65;
    }

    // Equilibrium constraint: Penalize deviation from mean_residual to keep bin distribution uniform.
    // Reduced weight slightly to allow for local "Best Fit" dominance.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
