    // Dynamic New Bin Penalty: Increased pressure to reduce the "open_bins_count" inflation.
    if bin_residual == bin_capacity {
        score += 78.0 + (open_bins_count as f64 * 2.1);

        // Adaptive threshold: If mean_residual is high, discourage new bins more aggressively.
        if mean_residual > (bin_capacity as f64 * 0.35) {
            score += 42.0;
        }
    }

    // Criticality constraint: Use fitting_bins_count to prevent orphaned items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Late-stream compaction: Shift strategy to force residual reduction in the final 15%.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.65;
    }

    // Entropy control: Keep residuals close to the global mean to avoid outlier bins,
    // but scale by the inverse of remaining items to allow more flexibility early on.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    let entropy_weight = 0.25 * (1.0 - progress);
    score += residual_diff * entropy_weight;

    // Final sanity check: Extremely tight fits (near zero) are highly prioritized.
    if post_residual < 8 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

