    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
        // Shift score towards filling bins with larger current residuals
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // 7. Variance Balancing: Avoid extreme outliers in residual distribution
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual)
    // We prioritize bins that create the smallest remaining space.

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that accommodate it.
    // We penalize bins that leave a residual smaller than the next item if possible.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0; // Penalty for stranding the next item
        } else if post_residual >= next_item_size {
            score -= 10.0; // Reward for enabling the next item
        }
    }

    // 3. Fragmentation Penalty: Avoid creating "dead" slivers (1-9 units)
    // Slivers are hard to fill with items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Harmonic Alignment: Favor filling bins to capacity fractions (e.g., 50, 33, 25)
    // This helps pack items that sum to common divisors of 100.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 15.0;
    }

    // 5. Global Load Balancing: 
    // If we have many open bins, push to pack tighter (penalize new bin creation).
    // If fitting_bins_count is 1, this is the only choice; we reduce the penalty for poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Strong penalty for opening a new bin unnecessarily
        } else {
            score -= 50.0; // Must open a new bin
        }
    }

    // 6. Mean Residual Sensitivity:
    // If the mean residual is high, we are under-utilizing bins; be more aggressive with packing.
    if mean_residual > 30.0 {
        score -= (mean_residual / 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
