    }

    // Scarcity constraint: If only one bin fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // End-of-stream compaction:
    // In the final 15%, prioritize closing bins (filling them as much as possible).
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.75;
    }

    // Balancing: 
    // Minimize the variance of residuals across open bins to keep them "equally" available.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.25;

    // Adaptive Penalty: Penalize bins that are significantly emptier than the global mean 
    // when we have many open bins, to encourage consolidation.
    if open_bins_count > 10 && post_residual > (mean_residual as u32 + 15) {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
