                let utilization_gain = (next_item_size as f64) / (bin_residual as f64 + 1.0);
                score -= 50.0 * utilization_gain;
            } else {
                // Penalize if the current bin cannot hold the next item but others might
                score += 15.0;
            }
        }

        // 4. Scarcity Logic: Force consolidation into the few available fitting bins
        if fitting_bins_count <= 2 {
            score -= 110.0 / (fitting_bins_count as f64);
        }

        // 5. Global Mean Alignment: penalize deviation from the average bin filling
        // This keeps the packing uniform, preventing extreme outliers in residual sizes
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.25;
    }

    // 6. Terminal Phase: Aggressive packing in the final 10% of the stream
    if progress > 0.90 {
        score -= (bin_capacity - post_residual) as f64 * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
