    // Global Mean Correction: Favor bins that maintain a residual near the historical mean.
    // This helps stabilize the distribution of items across bins and prevents "outlier" bins.
    let residual_bias = (post_residual as f64 - mean_residual) * 0.35;
    score += residual_bias;

    // End-game strategy: When nearing the end, prioritize filling bins with the 
    // largest current capacity (most empty) to minimize the number of final bins.
