    // 2. Harmonic Class Logic: Reward placements that leave "useful" residuals.
    // Residuals that are multiples of common item sizes (e.g., 20, 25) are more versatile.
    let remainder = post_residual % 20;
    score += (remainder as f64).powi(2) * 0.1;

