        }

        // Adaptive Lookahead: prioritize bins that accommodate the next item efficiently.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward bins that maintain a "useful" residual after the next item.
                let remainder = post_residual - next_item_size;
                if remainder == 0 {
                    score -= 50.0; // Perfect fit bonus
