        // Global density management:
        // Penalize bins that deviate from the global mean residual to encourage uniform filling.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.25;
    }

    // End-of-stream cleanup: aggressively fill bins as we near the end.
