    let progress = step_index as f64 / total_items as f64;

    // 1. Base cost is the remaining space (Best Fit approach).
    let mut score = post_residual as f64;

    // 2. Harmonic Penalty: Penalize residuals that cannot fit common items (10-40 range).
    // We favor residuals that are either 0 (perfect fit) or >= next_item_size.
    if !is_new_bin {
        if post_residual > 0 && post_residual < next_item_size {
            score += 45.0; // Heavy penalty for creating a "dead" gap that cannot fit the lookahead.
        }

        // Reward residuals that are multiples of 10 or 20, as these often align with item clusters.
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // 3. New Bin Thresholding: Only open a new bin if the mean residual is already high
    // or if the current bin is "strangling" the item flow.
    if is_new_bin {
        // If we have many bins open, penalize opening more unless we have no choice.
        score += (open_bins_count as f64 * 2.0);

        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score -= 100.0; 
        } else {
            // Otherwise, heavily penalize opening a new bin if existing ones have space.
            score += 60.0;
        }
    }

    // 4. Dynamic scaling based on stream progress.
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    score += (progress * 10.0);

    // 5. Lookahead coupling: If current post_residual is large enough for next_item_size, reward it.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score: Favor tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // 1. Fragment Penalty: Exponentially penalize small, unusable voids.
    // Small voids (1-20) are highly likely to remain unused in a greedy stream.
    if post_residual > 0 && post_residual < 20 {
        score += 55.0 + (20.0 - post_residual as f64) * 2.0;
