    // 2. Lookahead Integration: Reward placement that makes the next item fit perfectly.
    // We prioritize bins that leave exactly 0 or very little space after the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward "near-perfect" lookahead fit, penalize large gaps
            score -= (45.0 - (slack as f64 * 0.5)).clamp(0.0, 45.0);
        } else {
            // Penalize bins that cannot accommodate the next item (Lookahead Block)
            score += 25.0;
        }
    }

    // 3. Dynamic New Bin Control
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Base penalty for new bin + linear growth based on open bin count to force compaction
        score += 75.0 + (open_bins_count as f64 * 2.5);

        // If we are late in the stream, make opening new bins even costlier to force final compaction
        if progress > 0.75 {
            score += 40.0;
        }
    }

    // 4. Scarcity & Criticality: If only one bin fits, take it immediately.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // 5. Mean Residual Alignment: Favor bins that keep the bin closer to the global mean,
    // which statistically helps maintain a more uniform bin fill rate.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.25;

    // 6. Progressive Compaction: In the final stages, specifically prioritize filling
    // bins that are already the most empty (highest residual) to consolidate usage.
    if progress > 0.90 && bin_residual != bin_capacity {
        score -= (bin_capacity - post_residual) as f64 * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
