        score += 45.0 + (open_bins_count as f64 * 2.5) - (progress * 10.0);
    }

    // 3. Lookahead heuristic: If the next item fits into the current post_residual, 
    // reward this placement (Best-Fit-Decreasing influence).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // 4. Tightness reward: If this placement leaves very little room, it is excellent.
    if post_residual < 5 {
        score -= 15.0;
    }

    // 5. Global Load Balance: If the mean residual is high, we are being too loose.
    // Penalize bins that increase the mean residual further.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
