    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.35;

    // Mutation 7: Proactive Density Boost.
    // Reward bins that have high utilization relative to current mean.
    if (bin_capacity - post_residual) > (bin_capacity - mean_residual as u32) {
