    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Penalty for blocking the next item (preventing a potential future fit)
        score += 25.0;
    }

    // Dynamic New Bin Penalty: Increased pressure to reuse existing capacity.
    if bin_residual == bin_capacity {
        let density_factor = (open_bins_count as f64 * 2.2) + (mean_residual * 0.8);
        score += 75.0 + density_factor;
    }

    // Scarcity constraint: Strengthen the pull of the only-fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 140.0;
    }

    // Progression awareness: Shift from "fill empty" to "consolidate" in final 15%.
    // Use the bin_residual to prioritize filling the most crowded bins near the end.
    if progress > 0.85 {
        score -= (bin_capacity - bin_residual) as f64 * 0.65;
    }

    // Balancing: Keep residuals aligned with the mean, but penalize volatility
    // more heavily in the mid-game to maintain a stable packing footprint.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22 * (1.0 - (progress - 0.5).abs());

    // Final sanity check: discourage extremely large residuals if better options exist
    if post_residual > (bin_capacity / 2) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
