    if post_residual > 0 && post_residual < 33 {
        let penalty = 55.0 - (post_residual as f64 * 0.9);
        score += penalty.max(12.0);
    }

    // Advanced Lookahead: reward placement that creates a state where the next item fits perfectly.
    // If next_item_size is large, we prioritize creating a bin that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = (post_residual - next_item_size) as f64;
            score -= (55.0 - tightness * 0.5);
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a state that forces a new bin for the next item.
            score += 22.5;
        }
    }

    // New Bin Penalty: Strengthened against premature creation.
    if bin_residual == bin_capacity {
        // Base cost + density-aware scaling + progression-aware pressure
        let dynamic_new_bin_cost = 75.0 + (open_bins_count as f64 * 1.8) + (progress * 40.0);
        score += dynamic_new_bin_cost;

        // If current mean_residual is high, we have capacity in existing bins.
        if mean_residual > 25.0 {
            score += 45.0;
        }
    }

    // Scarcity constraint: If few options exist, prioritize existing bins to preserve new ones.
    if fitting_bins_count > 0 && fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 140.0 / (fitting_bins_count as f64);
    }

    // Tail-end compaction: Heavily favor filling bins completely when near the end of the stream.
    if progress > 0.92 {
        score -= (bin_capacity - post_residual) as f64 * 0.85;
    }

    // Variance control: Keep residuals close to the global mean to avoid outlier fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
