    // Scarcity constraint: Absolute priority for unique fitters.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // Tail-end optimization: Aggressively fill empty space when stream concludes.
    if progress > 0.88 {
        // Higher weight on filling largest residuals first.
        score -= (bin_capacity - post_residual) as f64 * 0.75;
    }

    // Balancing: Penalize deviation from the mean, but weight it against 
    // the current packing density (higher mean_residual = higher tolerance).
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    // Tie-breaker: If residuals are equal, prefer bins with more items already inside 
    // to keep the distribution of bin-fillings dense.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
