    // 2. Lookahead Synergy: If post_residual perfectly matches or closely fits the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for creating a perfect fit for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (50.0 - diff).max(0.0);
        } else {
            // Penalty for not being able to fit the next item when we could have chosen better
            score += 20.0;
        }
    }

    // 3. Global Efficiency: If the current bin is significantly emptier than the mean, 
    // prioritize filling it to keep the average utilization high.
    if (bin_residual as f64) > mean_residual {
        score -= 15.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (to avoid fragmentation)
        // or if the current options are extremely poor (high post_residual).
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression Scaling: As the stream nears the end, be more conservative (avoid new bins).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (progress * 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
