    if bin_residual == bin_capacity {
        let density_pressure = (item_size as f64 / (mean_residual + 0.1)).clamp(0.5, 2.0);
        score += 75.0 + (open_bins_count as f64 * 1.8) * density_pressure;

        if mean_residual > 25.0 {
            score += 45.0;
        }
    }

    // Scarcity constraint:
    // If only one bin fits, ensure it's picked, but reduce the "desperation" 
    // if the resulting residual is extremely poor (wastage-aversion).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 140.0 * (1.0 - (post_residual as f64 / bin_capacity as f64) * 0.2);
    }

    // Late-stage compaction:
    // In the last 15%, prioritize bins that are already partially full to force closure.
    if progress > 0.85 {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 60.0;
    }

    // Variance Dampening:
    // Penalize outliers from the mean_residual less aggressively than the parent to 
    // allow for more flexibility in bin selection early in the stream.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

