        let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= (48.0 * fit_tightness) * (1.0 + fullness);
    }

    // New Bin Penalty: Dynamic cost-benefit analysis of opening a new container.
    if is_new_bin {
        // Base penalty grows with open_bins_count to encourage tighter packing in existing bins.
        score += 72.0 + (open_bins_count as f64 * 1.8);

        // If current mean_residual is high, we have excessive slack; discourage new bin usage.
        if mean_residual > 28.0 {
            score += 45.0;
        }

        // Late-stage compaction: Discourage new bins when the stream is nearly finished.
        if progress > 0.92 {
            score += 150.0;
        }
    } else {
        // Scarcity constraint: If this is the only bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 140.0;
        }
    }

    // Progression awareness: As we approach the end, shift from "Tightest Fit" to "Emptying Bins".
    // Prioritize bins that already have low residuals to finish them off.
    if progress > 0.82 {
        score -= (bin_capacity - bin_residual) as f64 * 0.55;
    }

    // Entropy Control: Penalize deviations from the running mean residual to keep bin states uniform.
    // This reduces the variance of bin states, keeping the "best fit" options more predictable.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
