pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual ranges that are too small to fit typical items.
    // Gaps between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item could potentially fit into the post_residual,
    // reward this bin to keep the next item compact.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Bin count pressure: If we are deep into the stream, penalize creating new bins.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Heavy penalty for opening new bins when progress is high and we have open bins.
        score += (open_bins_count as f64 * 10.0) * (1.0 + progress);
    }

    // 4. Fitting constraints: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Balance residuals: Favor bins that keep the mean residual of open bins 
    // closer to the item_size, reducing fragmentation.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Penalty for fragmentation: Small post_residuals are expensive unless they are 0.
    // Increased slope for mid-range fragmentation to push for tighter packing.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 55.0;
        } else if post_residual < 30 {
            score += 20.0;
        }
    }

    // Lookahead: If next_item_size fits, prioritize this bin with a non-linear weight.
    if next_item_size > 0 && post_residual >= next_item_size {
        let efficiency_gain = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 35.0 + (efficiency_gain * 15.0);
    }

    // Dynamic New Bin Penalty:
    // If we have fitting bins, opening a new one is a last resort.
    if bin_residual == bin_capacity {
        let base_new_bin_penalty = 75.0 + (open_bins_count as f64 * 1.2);
        score += base_new_bin_penalty;

        // If the item is small, opening a new bin is very inefficient.
        if item_size < 40 {
            score += 40.0;
        }
    } else {
        // Scarcity constraint: If this is the only bin that fits the item, make it extremely attractive.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // Progression: As we approach the end of the stream, prioritize filling existing bins.
    if progress > 0.85 {
        score -= (bin_capacity - bin_residual) as f64 * 0.6;
    }

    // Balancing: Favor bins that maintain a lower residual than the global mean to leave room for large items.
    let residual_diff = post_residual as f64 - mean_residual;
    if residual_diff < 0.0 {
        score += residual_diff * 0.25;
    } else {
        score += residual_diff * 0.1;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Fragmentation penalty: penalize "slivers" that are too small to hold common items.
    // Enhanced with non-linear scaling for very small residuals.
    if post_residual > 0 && post_residual < 22 {
        score += 55.0 + (22.0 - post_residual as f64).powi(2) * 0.5;
    }

    // Lookahead: If next_item_size fits, incentivize this bin. 
    // Reward is proportional to how much "slack" is saved (avoiding fragmentation).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Dynamic New-Bin Thresholding:
    // If we are early in the stream, be very conservative about opening new bins.
    // If we are late, be more aggressive to clear remaining items.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 75.0 + (open_bins_count as f64 * 1.8);
        if progress > 0.92 {
            new_bin_penalty -= 40.0;
        }
        score += new_bin_penalty;
    } else {
        // If this bin is not new, reward "Best Fit" behavior (low post_residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Scarcity logic: If this is the only bin that can accommodate the item, 
    // make it extremely attractive to avoid unnecessary new-bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Balancing: Keep residuals clustered to maintain uniform bin state.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.25;

    // Perfect fit bonus: Heavy reward for filling a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Global Consolidation: Penalize the total number of bins to bias towards denser packing.
    score += (open_bins_count as f64 * 2.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, if the post_residual is exactly 0, we reward it heavily as a perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // we lower the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.8; 
    }

    // 3. Mean Residual Balancing: If the current bin's residual is significantly lower than 
    // the global mean, we treat it as a "tight" bin and penalize it slightly to avoid 
    // fragmenting space, unless it's the only bin left.
    if (bin_residual as f64) < mean_residual && fitting_bins_count > 1 {
        score += 15.0;
    }

    // 4. New Bin Constraint: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current item is large or no other bins offer a good fit.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 45.0;
        // Reduce cost if the item is large (e.g., > 70) as it's hard to fit elsewhere
        if item_size > 70 {
            score -= 30.0;
        }
    }

    // 5. Progression weighting: As we approach the end of the stream, 
    // prioritize closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

