    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals in the range (0, 10) heavily, as they are typically unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, avoid bins that leave too little space.
    // We penalize bins if they won't accommodate the next item when they otherwise could have.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - progress);
    }

    // Adaptivity: As the stream progresses, become more aggressive in packing tightly.
