    score += (open_bins_count as f64 * (1.0 - progress)) * 5.0;

    // Favor bins that align with the current average residual to maintain uniformity.
    score += (post_res - mean_residual).abs() * 0.5;

    // Special handling for the empty bin candidate (bin_residual == bin_capacity).
    // We make it harder to open a new bin if fitting_bins_count is high.
