    // New Bin Penalty: Dynamic cost to manage total open bins.
    if bin_residual == bin_capacity {
        score += 75.0 + (open_bins_count as f64 * 2.2);

        // If mean_residual is high, we have wasted space; make opening new bins even more expensive.
