pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // 1. Adaptive Fragmentation Penalty: 
    // Refined to identify "unfillable" slivers based on typical item distribution.
    if post_residual > 0 && post_residual < 28 {
        let sliver_penalty = 85.0 + (28.0 - post_residual as f64).powi(2) * 0.35;
        score += sliver_penalty * (1.0 + (open_bins_count as f64 * 0.03));
    }

    // 2. Enhanced Lookahead with Non-linear Scaling:
    // Reward bins that preserve capacity for the next item, heavily penalizing 
    // placement that makes the next item impossible to fit in the current bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward preserving space that allows the next item to fit, 
            // prioritizing "just right" fits (slack near 0).
            let slack = post_residual - next_item_size;
            score -= 125.0 * (1.0 - (slack as f64 / bin_capacity as f64).powf(0.6));
        } else {
            // Significant penalty for obstructing the next item's potential fit.
            score += 115.0;
        }
    }

    // 3. Dynamic New Bin Constraint:
    // Calibrated to force compaction. The threshold for opening a new bin is 
    // dynamically linked to the current average residual to prevent premature expansion.
    if bin_residual == bin_capacity {
        score += 185.0 + (open_bins_count as f64 * 7.5);
        if mean_residual > 20.0 {
            score += 105.0;
        }
    }

    // 4. Scarcity Logic:
    // High-priority incentive to use the only viable bin to avoid forced new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 750.0;
    }

    // 5. Residual Homogeneity:
    // Penalize deviation from the mean, but scale by progress to tighten constraints at the end.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * (0.45 * (1.0 - progress * 0.5));

    // 6. Temporal Compaction:
    // Pivot from Best Fit to Fill-to-Capacity as we near the end of the stream (last 25%).
    if progress > 0.75 {
        // Aggressive incentive to finalize bins as we near the stream end.
        score -= (bin_capacity - post_residual) as f64 * 5.5;
    } else if progress < 0.20 {
        // Extreme early-stage conservatism to prevent opening multiple half-empty bins.
        score -= (bin_capacity - bin_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If we have a small residual, we want it to be 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Density Balancing: If we have many open bins, penalize residuals that are too large,
    // pushing items into bins that are already well-filled.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Critical Threshold: If this is the only fitting bin, reward it to prevent opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the current placement would result in a very poor residual (e.g., > 40).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && (mean_residual > 20.0 || next_item_size < 30) {
            score += 50.0; // Discourage new bin if existing bins have decent space
        } else {
            score += 15.0; // Base cost to open a new bin
        }
    }

    // 6. Harmonic Class Logic: Prefer filling bins to specific modular thresholds.
    // This helps group items of similar sizes to maximize packing efficiency.
    let bucket = post_residual % 20;
    if bucket < 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // 1. Adaptive Fragmentation Penalty: 
    // Target residuals that are likely to be unusable for common items (1-32).
    // Penalize the "sliver" range more aggressively if we have plenty of open bins.
    if post_residual > 0 && post_residual < 32 {
        let sliver_penalty = 68.0 + (32.0 - post_residual as f64).powi(2) * 0.15;
        score += sliver_penalty * (1.0 + (open_bins_count as f64 * 0.06));
    }

    // 2. Enhanced Lookahead:
    // Reward bins that leave space for the next item, prioritizing exact matches.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Stronger weight on preserving space for the next item to minimize bin count.
            score -= 85.0 * (1.0 - (slack as f64 / bin_capacity as f64).powf(0.7));
        } else {
            // Penalty for blocking the next item if it could have fit elsewhere.
            score += 75.0;
        }
    }

    // 3. Dynamic New Bin Constraint:
    // Heavier penalty for new bins to force compaction, scaled by open_bins_count.
    if bin_residual == bin_capacity {
        score += 125.0 + (open_bins_count as f64 * 5.5);
        // If the mean residual is high, we have capacity in existing bins; make new bin very unattractive.
        if mean_residual > 20.0 {
            score += 75.0;
        }
    }

    // 4. Scarcity Logic:
    // Ensure we don't waste the only viable bin for the current item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // 5. Variance Balancing:
    // Penalize deviation from the mean_residual to prevent extreme bin imbalances.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.45;

    // 6. Temporal Compaction:
    // As the stream ends, prioritize clearing out bins by filling them.
    // Use a steeper ramp-up for late-stage efficiency.
    if progress > 0.80 {
        score -= (bin_capacity - post_residual) as f64 * 2.2;
    } else if progress < 0.15 {
        // Early-stage: prioritize packing into existing bins to avoid unnecessary growth.
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

