    // As the stream ends, prioritize filling the most empty bins to reduce the total count.
    // Aggressive push in the final 15% to finalize packing.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 1.8;
    } else if progress < 0.10 {
        // Early-stage: prioritize packing into existing bins to avoid unnecessary growth.
        score -= (bin_capacity - bin_residual) as f64 * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical items.
    // Given item range 10..80, residuals < 10 are highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bins Pressure: Penalize opening a new bin if the item could fit elsewhere.
    // If this is a new bin (bin_residual == bin_capacity) and we have fitting bins, heavily penalize.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0 + (open_bins_count as f64 * 5.0);
    }

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual, reward this placement.
