    // 4. Density Balancing: If the current bin is already quite full, prioritize finishing it.
    // Encourage filling bins that are already "near full" to reduce open_bins_count.
    if post_residual < 15 {
        score -= 10.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
