        }
    }

    // Criticality: If only one bin can fit the item, it is non-negotiable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Progression awareness: 
    // Mid-stream (0.3 - 0.8): Favor balancing residuals.
    // Late-stream (> 0.85): Aggressively prioritize filling the most empty bins to close them.
    if progress > 0.85 {
