    // Reward placement that leaves a residual perfectly matched to the next item,
    // but subtract a penalty if it creates a "near-miss" (residual < next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let efficiency = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 52.0 * efficiency;
        } else if post_residual > 0 {
            score += 20.0; // Penalty for blocking the next item
        }
    }

    // New Bin Penalty:
    // Dynamic thresholding based on open_bins_count to enforce denser packing.
    if bin_residual == bin_capacity {
        let base_new_bin_cost = 72.0 + (open_bins_count as f64 * 1.8);
        score += if mean_residual > 25.0 { base_new_bin_cost + 40.0 } else { base_new_bin_cost };
    }

    // Scarcity constraint:
    // If this is the only bin that fits the item, prioritize it to avoid premature bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Late-stage compaction:
    // In the final 20% of the stream, aggressively prioritize filling bins with the 
    // largest residuals to minimize total bin count at the tail end.
    if progress > 0.80 {
        score -= (bin_capacity - post_residual) as f64 * 0.7;
    }

    // Residual Variance Balancing:
    // Penalize outliers from the mean_residual to keep bin distribution uniform,
    // which statistically improves the probability of future items fitting.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.22;

    // Density normalization:
    // Minor correction to favor bins that are already partially filled if they 
    // are reaching capacity, reducing the count of bins with very low utilization.
    if bin_residual < (bin_capacity / 2) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

