    // fit is extremely poor (post_residual is large).
    if bin_residual == bin_capacity {
        // If we are considering a new bin, only do so if it's "cleaner" than
        // the average state of existing bins.
        score += mean_residual * 1.2;
    } else {
        // Encourage utilizing existing bins if they have space.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. Final Critical Fit: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
