    }

    // 4. Scarcity Logic:
    // High-priority incentive to use the only viable bin to avoid forced new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 750.0;
    }

    // 5. Residual Homogeneity & Progress Pivot:
    // Penalize deviation from the mean, but pivot to filling bins as we approach end-of-stream.
    let dev = (post_residual as f64 - mean_residual).abs();
    let homogeneity_weight = 0.4 * (1.0 - progress);
    score += dev * homogeneity_weight;

    // 6. End-Game Compaction:
