    let progress = step_index as f64 / total_items as f64;

    // Fragmentation penalty refinement: tightened the window to focus on "unusable" gaps
    // that are too small for common items but large enough to cause bin bloat.
    if post_residual > 0 && post_residual < 18 {
        score += 62.0 - (post_residual as f64 * 0.8);
    }

    // Lookahead: Enhanced sensitivity to the next item.
    // If the next item fits perfectly in the residual, we prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 48.0 * fit_quality;
    }

    // New Bin Logic: Dynamic thresholding based on stream progression.
    if bin_residual == bin_capacity {
        // Base penalty for new bin + linear scaling with current footprint
        score += 84.0 + (open_bins_count as f64 * 1.5);

        // If the stream is nearly over, penalize new bin creation more harshly to force consolidation
        if progress > 0.85 {
            score += 45.0;
        }

        // If the current item is small, force it into existing bins unless they are nearly full
        if item_size < 45 {
            score += 38.0;
        }
    } else {
        // Reward filling a bin to completion (Perfect Fit)
        if post_residual == 0 {
            score -= 75.0;
        }
    }

    // Scarcity: High reward for using a bin when it's the only one that fits.
    // Increased weight to prevent orphans.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Progression: Dynamic weighting of residuals.
    if progress > 0.92 {
        // End-game: aggressive packing to empty existing bins
        score -= (bin_capacity - post_residual) as f64 * 0.85;
    } else {
        // Mid-stream: minimize variance against the mean residual to maintain packing homogeneity
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.35;

        // Anti-clumping: if we have many bins, penalize residuals that are significantly larger than the mean
        if open_bins_count > 10 && post_residual > (mean_residual as u32) {
            score += (post_residual as f64 - mean_residual) * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
