    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 2. Lookahead mechanism: If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_diff = (post_residual - next_item_size) as f64;
