    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Mean residual balancing: Penalize creating bins that deviate significantly from the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Last chance protection: If this is the only bin that can fit the item, lower the penalty significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progressive tightening: As we approach the end of the stream, prioritize space density (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

