    let progress = step_index as f64 / total_items as f64;

    // Fragmentation penalty: Refined to identify "dead zones" where small items cannot fit.
    // Increased penalty for mid-range residuals that are too small for median-sized items.
    if post_residual > 0 && post_residual < 26 {
        score += 62.0 - (post_residual as f64 * 0.8);
    }

    // Lookahead: Enhanced sensitivity to next_item_size. 
    // Reward bins that leave exactly enough room for the next item to minimize future fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 52.0 * fit_quality;
        // Anti-starvation: penalize if next_item_size is large and this bin becomes too tight for it.
        if next_item_size > 70 && post_residual < 75 {
            score += 40.0;
        }
    }

    // New Bin Logic: Adjusted thresholding for opening new bins.
    if bin_residual == bin_capacity {
        score += 88.0 + (open_bins_count as f64 * 2.1);
        if mean_residual > 22.0 {
            score += 45.0; 
        }
        // Quadratic penalty for starting new bins with small items
        if item_size < 50 {
            score += (50.0 - item_size as f64) * 1.5;
        }
    } else {
        // Reward perfect fills more aggressively
        if post_residual == 0 {
            score -= 85.0;
        } else if post_residual < 8 {
            score -= 20.0;
        }
    }

    // Scarcity: Increased weight for unique fitting bins to prevent bin-sprawl.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    }

    // Progression: Dynamic weighting.
    if progress > 0.92 {
        // Late stage: aggressive consolidation to minimize trailing bin count.
        score -= (bin_capacity - post_residual) as f64 * 0.95;
    } else {
        // Early/Mid stream: balance residuals against the global mean to maintain packing density.
        // Penalty for deviating from the mean is now scaled by current open bin density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.35 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Penalty for creating "stranded" space (too small for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. 2-Step Lookahead: Reward bins that fit the next item perfectly (Best Fit approach)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (50.0 / (1.0 + diff));
        } else {
            // Penalize if the current placement prevents the next item from fitting
            score += 15.0;
        }
    }

    // 4. Global state optimization: Keep mean residual low
    // If the current bin's residual is significantly better than the global mean, reward it.
    let residual_improvement = mean_residual - (post_residual as f64);
    score -= residual_improvement * 0.5;

    // 5. Urgency: If this is the only bin that fits the current item, prioritize it highly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progression factor: Be more conservative with new bins as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 20.0);
    }

    score
}

