    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // to keep bins tightly packed.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead mechanism: If the next item fits into the post_residual,
    // prioritize this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Global state: Penalize opening a new bin if we have plenty of open bins
    // that are already quite full (low mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 120.0 * (1.0 - (mean_residual / bin_capacity as f64));
        }
        // Increase penalty for opening new bins as the stream nears completion
        score += progress * 50.0;
    }

    // 4. Criticality: If this is the only bin that can fit the item,
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 5. Fragmentation avoidance: Penalize leaving a sliver of space (1-9)
    // that is unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

