        }
    }

    // 3. Dynamic New Bin Constraint:
    // Adjusted barrier to be more sensitive to item size and current density.
    if bin_residual == bin_capacity {
        let density_penalty = (mean_residual / bin_capacity as f64) * 250.0;
        score += 240.0 + (open_bins_count as f64 * 16.0) + density_penalty + (progress * 95.0);

        if item_size < 72 {
            score += 130.0;
        }
    }

    // 4. Scarcity Logic:
    // Stronger protection for the last viable bin to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 850.0;
    }

    // 5. Variance Balancing:
    // Non-linear penalty to force bin convergence toward the mean, tightened slope.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev.powf(1.45) * 1.8;

    // 6. Filling Reward:
    // Higher incentive for perfect utilization.
    if post_residual == 0 {
        score -= 360.0;
    }

    // 7. Adaptive Compaction:
    // Aggressive late-game consolidation with steeper power curve.
    if progress > 0.6 {
        score -= (bin_capacity - post_residual) as f64 * 9.2 * progress.powi(4);
    } else if progress < 0.2 {
        score -= (bin_capacity - bin_residual) as f64 * 1.6;
    }

    // 8. Residual Density Normalization:
    // Penalize empty space more strictly as total inventory grows.
    if open_bins_count > 3 {
        score += (bin_residual as f64 / bin_capacity as f64) * 85.0;
    }

    // 9. Global Capacity Pressure:
    // Non-linear penalty to prevent bin runaway, scaled by actual capacity.
    let capacity_threshold = (total_items / 80).max(5);
